<script setup lang="ts">
import { ref, computed, watch } from 'vue'
import Icon from './Icon.vue'
import UsageChart from './UsageChart.vue'
import WorkspaceGuide from './WorkspaceGuide.vue'
import PersonalSourcePanel from './PersonalSourcePanel.vue'
import CodexConnection from './CodexConnection.vue'
import ExistingConversations from './ExistingConversations.vue'
import type { QuotaState } from './types'
const props = defineProps<{ quota: QuotaState; busy: string }>()
const emit = defineEmits<{ action: [method: string, params: Record<string, unknown>, message: string]; error: [message: string];notice:[message:string] }>()
const mode = ref<'plus' | 'pro'>(props.quota.config.mode), threshold = ref({...props.quota.config.thresholds[mode.value]})
const autoResume = ref(props.quota.config.auto_resume), bucket = ref(props.quota.config.bucket)
const teamPending=ref(false),continuationDirty=ref(false)
const shared = computed(()=>props.quota.control?.scope==='shared'), selected = ref(''), prompt = ref(''), cwd = ref(''), taskOpen = ref(false)
const defaults={enabled:false,primary:100000,secondary:1000000}
const capEnabled=ref(props.quota.config.caps?.[mode.value]?.enabled || false),capPrimary=ref(props.quota.config.caps?.[mode.value]?.primary || defaults.primary),capSecondary=ref(props.quota.config.caps?.[mode.value]?.secondary || defaults.secondary)
const profileName=computed(()=>props.quota.config.profiles?.[props.quota.config.active_profile]?.name || '我的用量')
const profileDraft=ref(''),importing=ref(false)
const protectedCount=computed(()=>props.quota.choices.filter(c=>props.quota.config.threads[c.id]?.selected).length)
const preparedChoice=computed(()=>props.quota.choices.find(c=>{const r=props.quota.config.threads[c.id];return r?.prepared&&r.cwd?.toLowerCase()===cwd.value.toLowerCase()}))
const displayedCaps=computed(()=>({enabled:capEnabled.value,primary:capPrimary.value,secondary:capSecondary.value}))
const dirty = computed(() => mode.value !== props.quota.config.mode || (['primary','secondary'] as const).some(k=>threshold.value[k]!==props.quota.config.thresholds[mode.value][k]) || autoResume.value !== props.quota.config.auto_resume || bucket.value !== props.quota.config.bucket || capEnabled.value !== (props.quota.config.caps?.[mode.value] || defaults).enabled || capPrimary.value !== (props.quota.config.caps?.[mode.value] || defaults).primary || capSecondary.value !== (props.quota.config.caps?.[mode.value] || defaults).secondary)
const stale = computed(() => !props.quota.updated || !!props.quota.error || Date.now() / 1000 - props.quota.updated > 65)
const locked = computed(() => props.quota.enabled || !!props.busy || teamPending.value || importing.value)
const windows = computed(() => ['primary', 'secondary'].map((key, i) => ({ key, title: i ? '长期额度' : '短期额度', data: props.quota.windows.find(w => w.key === key) })))
const timestamp = (t?: number) => t ? new Date(t * 1000).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }) : '服务端未提供'
const statusLabels: Record<string, string> = { watching: '监测中', interrupt_pending: '等待中断确认', paused: '已确认停止 · 等待满额', paused_idle:'空闲目标已暂停 · 等待满额', resume_pending: '续聊结果待核实' }
function hydrateCaps(){const cap=props.quota.config.caps?.[mode.value] || defaults;capEnabled.value=cap.enabled;capPrimary.value=cap.primary;capSecondary.value=cap.secondary}
watch(mode,value=>{threshold.value={...props.quota.config.thresholds[value]};hydrateCaps()})
watch(()=>props.quota.config.active_profile,hydrateCaps)

function save() { if(![capPrimary.value,capSecondary.value].every(v=>Number.isInteger(v)&&v>=1&&v<=1000000000))return emit('error','个人上限请输入 1–1,000,000,000 的整数 tokens。'); if (!Object.values(threshold.value).every(v=>Number.isInteger(v)&&v>=1&&v<=95)) return emit('error','短期、长期阈值都请输入 1–95 的整数。'); emit('action','quota.configure',{ mode: mode.value, threshold: threshold.value, autoResume: autoResume.value, bucket: bucket.value,caps:displayedCaps.value },'额度守护策略已保存。') }
async function chooseDirectory() { try { cwd.value = await window.aiLink.chooseDirectory() || cwd.value } catch (error) { emit('error',String(error)) } }
function startTask(){if(!cwd.value)return emit('error','请先选择工作区。');if(!preparedChoice.value)return emit('action','quota.prepare',{cwd:cwd.value},'对话已准备，尚未发送任务。确认守护开启后发送。');if(!props.quota.enabled)return emit('error','请先开启守护。');if(!prompt.value.trim())return emit('error','请输入要执行的任务。');emit('action','quota.chat',{prompt:prompt.value,cwd:cwd.value,threadId:preparedChoice.value.id},'已向受保护对话发送任务。')}
</script>
<template><div class="workspace-page">
  <section class="hero quota-hero compact-hero"><div class="hero-copy"><span class="eyebrow"><Icon name="shield" :size="15"/>CODEX QUOTA GUARD</span><h2>留一点余量，<span>让任务有续章。</span></h2><p>触及保留阈值时暂停，在额度恢复后继续。节奏由你决定。</p></div><div class="quota-hero-symbol" aria-hidden="true"><Icon name="shield" :size="68"/><span></span></div></section>
  <CodexConnection :quota="quota" :busy="busy" @action="(m,p,n)=>emit('action',m,p,n)" @error="emit('error',$event)"/>
  <div v-if="quota.error" class="notice warning" role="alert"><Icon name="info"/><span>{{ quota.error }}</span></div>
  <div class="notice neutral"><Icon name="info"/><span>下方百分比是共享账号的总剩余额度；个人历史只统计明确归属的对话 token 事件，两者不相互推算。</span></div>
  <div class="quota-layout"><section class="quota-budgets"><div class="quota-gauges"><article v-for="window in windows" :key="window.key" class="panel quota-gauge" :class="{ stale }"><div class="metric-top"><span>{{ window.title }}</span><span class="badge subtle">{{ window.data?.minutes ? (window.data.minutes >= 1440 ? `${Math.round(window.data.minutes/1440)} 天窗口` : `${window.data.minutes/60} 小时窗口`) : '等待数据' }}</span></div><div class="quota-number">{{ window.data ? `${window.data.remaining}%` : '—' }}<small>剩余</small></div><div class="progress-track" role="progressbar" :aria-label="window.title" :aria-valuenow="window.data?.remaining" aria-valuemin="0" aria-valuemax="100"><div :style="{ width: `${window.data?.remaining || 0}%` }"></div><i :style="{ left: `${quota.config.thresholds[quota.config.mode][window.key as 'primary'|'secondary']}%` }" :title="`保留阈值 ${quota.config.thresholds[quota.config.mode][window.key as 'primary'|'secondary']}%`"></i></div><div class="gauge-caption"><Icon name="clock" :size="14"/><span>{{ window.data ? `重置 ${timestamp(window.data.reset)}` : '尚无可用额度数据' }}</span></div></article></div><div class="freshness"><span class="status-dot" :class="{ live: quota.connected && !stale }"></span>{{ quota.updated ? `更新于 ${timestamp(quota.updated)} · 每 30 秒刷新` : '连接后显示服务端真实额度' }}<span v-if="stale && quota.connected" class="text-warning">数据暂不可用于续聊</span></div><div class="scope-note"><Icon name="eye"/><div><strong>已接管范围：{{ protectedCount }} 个已选目标</strong><p>{{ shared ? '共享模式仅列出当前进程已加载的对话。无法连接共享接口时，不会控制其他桌面窗口。' : '托管模式仅管理本应用创建的对话，不能控制另一个 Codex 桌面窗口。' }}</p></div></div></section>
    <section class="panel guard-settings"><div class="section-heading"><div><span class="eyebrow muted">YOUR PREFERENCES</span><h3>额度守护策略</h3></div><span class="badge" :class="{purple:quota.enabled}">{{ quota.enabled ? '守护中' : '已关闭' }}</span></div><div class="segmented" role="group" aria-label="计划模式"><button v-for="plan in (['plus','pro'] as const)" :key="plan" :class="{selected:mode === plan}" :disabled="locked" :aria-pressed="mode === plan" @click="mode=plan"><Icon :name="plan === 'plus' ? 'bolt' : 'layers'" :size="16"/>{{ plan === 'plus' ? 'Plus' : 'Pro' }}</button></div><fieldset class="quota-thresholds"><legend class="field-label">账号剩余额度限制</legend><div v-for="window in ([{key:'primary',title:'短期额度'},{key:'secondary',title:'长期额度'}] as const)" :key="window.key" class="threshold-window"><label class="field-label" :for="`quota-threshold-${window.key}`">{{ window.title }}<span>剩余 ≤ {{ threshold[window.key] }}% 时暂停</span></label><div class="number-input"><input :id="`quota-threshold-${window.key}`" v-model.number="threshold[window.key]" type="number" min="1" max="95" step="1" :disabled="locked"><span>%</span></div><div class="slider-row"><input v-model.number="threshold[window.key]" type="range" min="1" max="95" :disabled="locked" :aria-label="`调整${window.title}暂停阈值`"><span>1–95%</span></div></div><p class="micro-copy">两个窗口分别设置，任一达到对应阈值即触发保护。</p></fieldset><label v-if="quota.buckets.length > 1" class="field-label" for="quota-bucket">额度池<select id="quota-bucket" v-model="bucket" :disabled="locked"><option v-for="value in quota.buckets" :key="value">{{ value }}</option></select></label><div class="setting-switch-row"><div><strong>满额后自动恢复未完成对话</strong><small>所有窗口满额后，按下方每段对话的规则恢复</small></div><button class="switch" :class="{on:autoResume}" role="switch" :aria-checked="autoResume" aria-label="满额后自动恢复未完成对话" :disabled="locked" @click="autoResume=!autoResume"><span></span></button></div><div class="personal-cap-settings"><div class="setting-switch-row"><div><strong>个人用量上限</strong><small>仅约束「{{ profileName }}」· {{ mode.toUpperCase() }}</small></div><button class="switch" :class="{on:capEnabled}" role="switch" :aria-checked="capEnabled" aria-label="开启个人 token 上限" :disabled="locked" @click="capEnabled=!capEnabled"><span></span></button></div><div class="cap-inputs"><label class="field-label" for="personal-five-hour">近 5 小时上限<div class="number-input"><input id="personal-five-hour" v-model.number="capPrimary" type="number" min="1" max="1000000000" :disabled="locked || !capEnabled"><span>tokens</span></div></label><label class="field-label" for="personal-week">近 7 天上限<div class="number-input"><input id="personal-week" v-model.number="capSecondary" type="number" min="1" max="1000000000" :disabled="locked || !capEnabled"><span>tokens</span></div></label></div><p class="micro-copy">任一滚动窗口达到上限时，暂停本档案已选中守护的对话。tokens 不能换算为套餐额度百分比。按收到的用量事件执行，单次请求可能越过上限。</p></div><div class="button-row settings-actions"><button class="btn secondary" :disabled="locked || !dirty" @click="save">保存策略</button><button class="btn primary" :disabled="!quota.connected || !!busy || importing || teamPending || (!quota.enabled && (dirty || continuationDirty || !protectedCount || stale))" @click="emit('action','quota.arm',{ enabled: !quota.enabled },quota.enabled ? '额度守护已关闭。' : '额度守护已开启。')"><Icon :name="quota.enabled ? 'pause' : 'shield'" :size="17"/>{{ quota.enabled ? '关闭守护' : dirty ? '请先保存' : continuationDirty ? '请先保存对话规则' : '开启守护' }}</button></div><p class="micro-copy">Plus／Pro 各自保存短期、长期两个阈值，以账户实际套餐为准。额度快照存在延迟，无法精确到 token 停止。</p></section></div>
  <ExistingConversations :quota="quota" :busy="busy" @action="(m,p,n)=>emit('action',m,p,n)" @draft-change="continuationDirty=$event"/>
  <section class="personal-workspace"><div class="section-heading"><div><span class="eyebrow muted">PERSONAL USAGE · {{ mode.toUpperCase() }}</span><h3>个人流动历史</h3><p>独立于共享账号额度，仅记录明确归属给此档案的 tokens。</p></div><span class="badge subtle">自动更新</span></div><div class="panel personal-profile-bar"><label class="field-label">统计档案<select :value="quota.config.active_profile || 'me'" :disabled="locked || importing" aria-label="个人统计档案" @change="emit('action','quota.profile.select',{profileId:($event.target as HTMLSelectElement).value},'个人统计档案已切换。')"><option v-for="(profile,id) in (quota.config.profiles || {me:{name:'我的用量'}})" :key="id" :value="id">{{ profile.name }}</option></select></label><div class="profile-create"><label class="sr-only" for="profile-name">新档案名称</label><input id="profile-name" v-model="profileDraft" maxlength="24" placeholder="新档案名称" :disabled="locked || importing"><button class="btn secondary" :disabled="locked || importing || !profileDraft.trim()" @click="emit('action','quota.profile.create',{name:profileDraft.trim()},'个人统计档案已创建。')">新建档案</button></div></div><PersonalSourcePanel :quota="quota" :busy="busy" @action="(m,p,n)=>emit('action',m,p,n)"/><div v-if="quota.personal?.incomplete" class="notice warning"><Icon name="info"/><span>个人观测不完整。开启个人上限时会保守暂停归属对话，请核查记录，避免将缺失数据当作未消耗。</span></div><UsageChart :personal="quota.personal" :mode="mode" :caps="displayedCaps" :name="profileName"/><p class="micro-copy">托管对话接收实时用量事件，本机会话日志每 2 分钟补充一次。统计不读取账号百分比；团队记录请到独立的「多人用量」工作空间导入。</p></section>
  <section class="panel conversations"><div class="section-heading"><div><h3>受保护对话 <span class="count-badge">{{ quota.choices.length }}</span></h3><p>关闭守护、取消选择或出现新用户回合后，不再续接旧任务。</p></div><button class="btn secondary" :disabled="!quota.connected || shared" @click="taskOpen=!taskOpen"><Icon name="terminal" :size="17"/>{{ taskOpen ? '收起任务' : '新建托管任务' }}</button></div><WorkspaceGuide :selected-path="cwd"/><Transition name="expand"><div v-if="taskOpen" class="task-composer"><div class="notice neutral"><Icon name="info"/><span>托管任务使用只读工作区。需要审批的操作会被拒绝；请在完整 Codex 客户端中处理。</span></div><button class="directory-button" :disabled="!!busy" :title="cwd || '选择这次任务使用的项目文件夹'" @click="chooseDirectory"><Icon name="folder"/><span>{{ cwd || '选择工作区（文件夹）' }}</span><Icon name="chevron" :size="16"/></button><label class="sr-only" for="task-prompt">任务内容</label><textarea id="task-prompt" v-model="prompt" rows="4" maxlength="20000" placeholder="描述希望 Codex 分析的任务…" :disabled="!!busy"></textarea><div class="composer-footer"><span>{{ preparedChoice?(quota.enabled?'任务会发送到这个已准备的受保护对话':'已准备对话，请保存策略并开启守护'):'先准备对话，再开启守护并发送任务' }}</span><button class="btn primary" :disabled="!!busy || shared || !cwd || (preparedChoice ? (!quota.enabled || !prompt.trim()) : false)" @click="startTask"><Icon name="arrow" :size="17"/>{{ preparedChoice?(quota.enabled?'发送任务':'请先开启守护'):'准备受保护对话' }}</button></div></div></Transition></section>
  <p class="micro-copy section-note"><Icon name="info" :size="14"/>自动恢复只针对未完成且可控的目标；已完成对话不发送自动消息。应用需保持运行，重启后重新开启守护。</p>
</div></template>

<style scoped>
.quota-thresholds{display:grid;gap:12px;margin-bottom:18px}.quota-thresholds>legend{padding:0;margin-bottom:12px}.threshold-window{padding:13px 14px 5px;border:1px solid var(--line);background:var(--surface-input);border-radius:11px;min-width:0}.threshold-window>.field-label{display:flex;flex-wrap:wrap;justify-content:space-between;gap:6px;margin-bottom:10px}.threshold-window>.field-label>span{font-size:10px;line-height:1.7}.threshold-window .slider-row{margin-bottom:8px}.quota-thresholds>.micro-copy{font-size:11px;line-height:1.8}
</style>
